import{_ as r}from"./chunks/rak产品管理.rz20lI6C.js";import{_ as s,o as p,c as a,a2 as n}from"./chunks/framework.BXzK3EA4.js";const i="/assets/%E7%9B%AE%E6%A0%87vps1.BQ9TCcKn.png",o="/assets/%E5%8D%87%E9%99%8D%E7%BA%A7vps.CKaCYIgI.png",e="/assets/%E5%8D%87%E9%99%8D%E7%BA%A7%E9%85%8D%E7%BD%AE.UsGdKYx6.png",l="/assets/%E5%8D%87%E9%99%8D%E7%BA%A7%E7%BB%93%E7%AE%97%E9%A1%B5%E9%9D%A2.B_eAnUZO.png",g="/assets/%E5%8D%87%E9%99%8D%E7%BA%A7%E6%94%AF%E4%BB%98.BB8O2RyX.png",c="/assets/%E6%94%AF%E4%BB%98%E5%AE%8C%E6%88%903.Bfvctsr5.png",D=JSON.parse('{"title":"升降级","description":"","frontmatter":{"title":"升降级"},"headers":[],"relativePath":"beginners-guide/manage-products/upgrade-downgrade.md","filePath":"beginners-guide/manage-products/upgrade-downgrade.md","lastUpdated":1788259091000}'),d={name:"beginners-guide/manage-products/upgrade-downgrade.md"};function _(m,t,E,u,A,B){return p(),a("div",null,[...t[0]||(t[0]=[n('<p>购买 RakSmart 产品后，您可以根据需要，自主对产品的配置进行升级或降级操作。通过升降级，可满足您业务扩张的需求、优化云资源配置、应对业务负载变化 或节省成本等。</p><p>不同的产品，支持升降级的资源类型不同，例如产品规格、公网带宽配置、存储容量、资源包规格、云盘类型和资源参数等。本文主要介绍如何通过控制台进行产品升降级。</p><hr><h3 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><p>以 VPS 为例，如果需要对实例升降级，可前往 VPS 控制台，针对指定配置进行升降级操作。</p><ol><li><p>使用 RakSmart 账号登录 <a href="https://billing.raksmart.com/whmcs/index.php?rp=/user/security" target="_blank" rel="noreferrer">RakSmart 控制台</a>。</p></li><li><p>在控制台左侧导航<strong>产品管理</strong>区域，单击需要升降级的产品/服务名称进入<strong>我的产品与服务</strong>页面。</p><p><img src="'+r+'" alt="rak产品管理.png"></p></li><li><p>单击<strong>产品/服务</strong>名称，进入<strong>管理产品</strong>页面。</p><p><img src="'+i+'" alt="目标vps1.png"></p></li><li><p>在<strong>管理产品</strong>页面，单击<strong>升/降级</strong>。进入<strong>升级/降级</strong>页面。</p><p><img src="'+o+'" alt="升降级vps.png"></p></li><li><p>重新填写或选择需要升降级的配置。例如实例规格由计算型 1 核心 CPU 改选为计算型 2 核心 CPU。</p><p><img src="'+e+'" alt="升降级配置.png"></p></li><li><p>单击<strong>点击继续</strong>，进入<strong>升级/降级</strong>价格确认页面。确认页面展示哪些配置做了升降级，和对应的价格变化。</p><p><img src="'+l+'" alt="升降级结算页面.png"></p></li><li><p>确认升降级配置和价格没有问题后，单击<strong>点击继续</strong>。进入<strong>我的账单</strong>页面。</p><p><img src="'+g+'" alt="升降级支付.png"></p></li><li><p>在<strong>我的账单</strong>页面，选择支付方式或者使用余额支付。</p></li><li><p>付款成功。</p><p><img src="'+c+'" alt="支付完成3.png"></p></li><li><p>支付成功后，系统将自动完成配置调整。可在产品详情页查看更新后的配置信息，确认是否生效。</p></li></ol><hr><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p>对产品进行升降级会存在一些限制或影响，请留意操作界面的提示，或查看该产品的相关文档了解详情。</p><ol><li><p>不同产品升降级时可能会存在限制。</p><p>例如：实例的网络类型不允许改变；硬盘容量只允许升级，不支持降级。</p></li><li><p>升级与变配可能会对您的资源费用、生效时间、计费方式产生影响。</p><p>例如，升级时，可能需要您为当前计费周期的规格或配置补差价。</p></li><li><p>部分产品的升级与变配可能会对您的业务造成短暂影响。</p><ul><li>提前规划升级时间：建议选择业务低峰期执行升级 / 变配操作（如凌晨、节假日），最大程度降低对核心业务的影响。</li><li>备份业务数据与配置：操作前务必完成全量数据备份和关键配置文件导出，避免因升级异常导致数据丢失或配置错乱。</li><li>业务恢复后校验：升级完成后，需逐一验证业务功能、网络连通性、数据完整性，确认无异常后再恢复全量业务访问。</li><li>问题反馈：若遇任务卡顿、失败等异常，及时通过控制台工单系统或客服渠道反馈。</li></ul></li></ol>',10)])])}const k=s(d,[["render",_]]);export{D as __pageData,k as default};
